
export interface RecoveryTask {
  el: () => Element | null | undefined;
  build: () => void;
}

const BUDGET_MS = 12;
const SCAN = 40;
const MARGIN_PX = 600;

// Restores run in idle slices under a time budget, visible tasks first; a click on a
// task still waiting builds it straight away.
const queue: RecoveryTask[] = [];
let scheduled = false;

const now = (): number => (typeof performance === 'undefined' ? Date.now() : performance.now());

function planSlice(): void {
  if (scheduled) return;
  scheduled = true;
  const w = globalThis as unknown as {
    requestIdleCallback?: (cb: () => void, o?: { timeout: number }) => void;
  };
  if (typeof w.requestIdleCallback === 'function') w.requestIdleCallback(run, { timeout: 250 });
  else setTimeout(run, 0);
}

function pickVisible(): number {
  const h = typeof window === 'undefined' ? 0 : window.innerHeight;
  if (!h) return 0;
  const limit = Math.min(queue.length, SCAN);
  for (let i = 0; i < limit; i += 1) {
    const el = queue[i].el();
    if (!el || !el.isConnected) continue;
    const r = el.getBoundingClientRect();
    if (r.bottom >= -MARGIN_PX && r.top <= h + MARGIN_PX) return i;
  }
  return 0;
}

function run(): void {
  scheduled = false;
  const deadline = now() + BUDGET_MS;
  while (queue.length) {
    const t = queue.splice(pickVisible(), 1)[0];
    const el = t.el();
    if (el && el.isConnected) t.build();
    if (now() >= deadline) break;
  }
  if (queue.length) planSlice();
}

export function restoreLater(task: RecoveryTask): void {
  queue.push(task);
  planSlice();
}

export const recoveryQueue = (): number => queue.length;

export function restoreNow(): void {
  while (queue.length) {
    const t = queue.shift()!;
    const el = t.el();
    if (el && el.isConnected) t.build();
  }
}

export function forgetRecoveryQueue(): void {
  queue.length = 0;
}
