import { Show } from 'solid-js';
import type { JSX } from 'solid-js';
import { statusWord } from '../../model/parse.js';
import { text, view } from '../../stores/view.js';
import { TERM_BY_KEY } from './header.jsx';
import './shared.css';

export type CardKind = 'set' | 'request' | 'offer' | 'agreement';

export type RuleKind = 'permission' | 'prohibition' | 'duty' | 'offer' | 'inherited';

const PILL_CLASS: Record<CardKind, string> = {
  set: 'set', request: 'set request', offer: 'offer', agreement: 'agreement',
};
const PILL_KEY: Record<CardKind, string> = {
  set: 'kind.set', request: 'kind.request',
  offer: 'kind.offer', agreement: 'kind.agreement',
};

export const RULE_KEY: Record<RuleKind, string> = {
  permission: 'rule.permission', prohibition: 'rule.prohibition',
  duty: 'rule.duty', offer: 'rule.offer', inherited: 'rule.inherited',
};

export const ADD_RULE_KEY: Record<'permission' | 'prohibition' | 'duty', string> = {
  permission: 'edit.permission', prohibition: 'edit.prohibition', duty: 'edit.duty',
};

export function KindPill(props: { kind: CardKind }): JSX.Element {
  return (
    <span
      class={'kind-pill ' + PILL_CLASS[props.kind]}
      data-term={TERM_BY_KEY[PILL_KEY[props.kind]]}
    >{text(PILL_KEY[props.kind])}</span>
  );
}

export function RuleBadge(props: { kind: RuleKind; label?: string }): JSX.Element {
  return (
    <span
      class={'method ' + props.kind}
      data-term={TERM_BY_KEY[RULE_KEY[props.kind]]}
    >{props.label ?? text(RULE_KEY[props.kind])}</span>
  );
}

export function VersionChip(props: { status?: string | null }): JSX.Element {
  const show = () => !!props.status && props.status !== 'current';
  const word = () => {

    void view.lang;
    return statusWord(props.status);
  };
  return (
    <Show when={show()}>
      <span class={'vchip ' + props.status}>{word()}</span>
    </Show>
  );
}

// Same family as the version chip: a nameless policy is a state of the card,
// not an error, and it reads in the same place and the same shape.
export function NoIdChip(props: { show?: boolean }): JSX.Element {
  return (
    <Show when={props.show}>
      <span class="vchip noid" title={text('card.noIdHint')}>{text('card.noId')}</span>
    </Show>
  );
}

export function Chevron(props: {
  small?: boolean; large?: boolean; off?: boolean;
}): JSX.Element {
  return (
    <span
      class={'chev' + (props.small ? ' chev-sm' : '') + (props.large ? ' chev-lg' : '')
        + (props.off ? ' chev-off' : '')}
      aria-hidden="true"
    />
  );
}

// ONE RULE for every fold: a chevron with nothing behind it is disabled —
// dimmed, no pointer, aria-disabled on the control that carries it (the
// summary; the chevron itself is decoration) and a click that does nothing.
// Read reactively at the call site, so a fold comes on the moment content
// arrives — no reload.
export function emptyFold(empty: boolean): {
  'aria-disabled'?: 'true'; onClick?: (e: MouseEvent) => void;
} {
  if (!empty) return {};
  return {
    'aria-disabled': 'true',
    onClick: (e: MouseEvent) => e.preventDefault(),
  };
}
